package com.yihe.framework.ehr;
import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.beans.factory.annotation.Value;import org.springframework.web.bind.annotation.*;import javax.servlet.http.*;import java.nio.file.*;import java.util.*;import java.util.regex.*;import java.io.*;import static com.yihe.framework.ehr.EhrAccess.*;import static com.yihe.framework.ehr.EhrController.ok;
@RestController @RequestMapping("/ehr/api/message-templates")
public class MessageTemplateApi{
 private final EhrAccess access;private final EhrRepository db;private final ObjectMapper json=new ObjectMapper();@Value("${ehr.storage-root:${EHR_STORAGE_ROOT:D:/update}}") private String storage;
 private static final Pattern VARIABLE=Pattern.compile("\\{\\{\\s*([A-Za-z0-9_\\u4e00-\\u9fff.-]{1,80})\\s*\\}\\}|\\$\\{\\s*([A-Za-z0-9_\\u4e00-\\u9fff.-]{1,80})\\s*\\}");
 public MessageTemplateApi(EhrAccess a,EhrRepository d){access=a;db=d;}@ModelAttribute public void headers(HttpServletResponse r){r.setHeader("Cache-Control","private, no-store");}private String s(Object v){return v==null?"":String.valueOf(v);}private void check(boolean v,String m){if(!v)throw new EhrException(422,m);}private Path file(EhrActor a){return Paths.get(storage,".message-templates",Base64.getUrlEncoder().withoutPadding().encodeToString(digest(bytes(a.scope+":"+a.mode)))+".json");}
 @SuppressWarnings("unchecked") private List<Map<String,Object>> rows(Object v,int max){check(v instanceof List&&((List<?>)v).size()<=max,"列表格式无效或超过限制");List<Map<String,Object>> out=new ArrayList<>();for(Object r:(List<?>)v){check(r instanceof Map,"配置行无效");out.add((Map<String,Object>)r);}return out;}
 private String displayName(String category,String body,Object id){String label=category.isEmpty()?"原微信模板 "+id:category;String snippet=body.replaceAll("[\\r\\n\\t ]+"," ").trim();return snippet.isEmpty()?label:label+" · "+snippet.substring(0,Math.min(20,snippet.length()))+(snippet.length()>20?"…":"");}
 private Map<String,Object> initial(){List<Object> templates=new ArrayList<>(),categories=new ArrayList<>(),channels=new ArrayList<>();Set<String> names=new HashSet<>();for(Map<String,Object> row:db.all("SELECT T_ID id,T_Type sourceType,T_Classify name,T_TemContent body,T_Template_Id providerId FROM yh_template_type ORDER BY T_ID")){String category="wechat-"+s(row.get("sourceType")),name=s(row.get("name"));if(names.add(category))categories.add(map("id",category,"name",name.isEmpty()?"微信模板类型 "+row.get("sourceType"):name,"channel","wechat"));templates.add(map("id","wx-"+row.get("id"),"name",displayName(name,s(row.get("body")),row.get("id")),"code","WX-"+row.get("id"),"categoryId",category,"channel","wechat","scene","","audience","","body",s(row.get("body")),"providerId",s(row.get("providerId")),"enabled",true,"url","","revision",1));}
 for(Map<String,Object> row:db.all("SELECT sms_id id,smsname name,template_id providerId,template_type category,template_text body,template_genre scene FROM yh_jz_sys_sms ORDER BY sms_id")){String c="sms-"+s(row.get("category"));if(names.add(c))categories.add(map("id",c,"name",s(row.get("category")).isEmpty()?"短信通知":row.get("category"),"channel","sms"));templates.add(map("id","sms-"+row.get("id"),"name",s(row.get("name")).isEmpty()?"原短信模板 "+row.get("id"):row.get("name"),"code","SMS-"+row.get("id"),"categoryId",c,"channel","sms","scene",s(row.get("scene")),"audience","","body",s(row.get("body")),"providerId",s(row.get("providerId")),"enabled",true,"url","","revision",1));}
 for(String c:Arrays.asList("wechat","sms","system","email")){if(!names.contains(c)){categories.add(map("id",c,"name",c.equals("wechat")?"微信通知":c.equals("sms")?"短信通知":c.equals("system")?"系统消息":"邮件通知","channel",c));}channels.add(map("id",c,"name",c.equals("wechat")?"微信":c.equals("sms")?"短信":c.equals("system")?"系统消息":"邮件","enabled",false,"sender","","description","","quietStart","","quietEnd",""));}return map("version",0,"templates",templates,"categories",categories,"channels",channels,"rules",new ArrayList<>(),"previews",new ArrayList<>(),"history",new ArrayList<>());}
 @SuppressWarnings("unchecked") private Map<String,Object> read(EhrActor a)throws IOException{Path p=file(a);if(!Files.exists(p))return initial();check(Files.size(p)<=8388608,"模板配置过大");return json.readValue(Files.readAllBytes(p),Map.class);}private void write(EhrActor a,Map<String,Object> data)throws IOException{byte[] content=json.writeValueAsBytes(data);check(content.length<=8388608,"模板配置超过8MB");Path p=file(a);Files.createDirectories(p.getParent());Path tmp=Files.createTempFile(p.getParent(),"message-",".tmp");try{Files.write(tmp,content);try{Files.move(tmp,p,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(AtomicMoveNotSupportedException ex){Files.move(tmp,p,StandardCopyOption.REPLACE_EXISTING);}}finally{Files.deleteIfExists(tmp);}}
 private void text(Map<String,Object> r,String k,int max,boolean required){String v=s(r.get(k));check(v.length()<=max&&(!required||!v.trim().isEmpty()),"字段 "+k+" 为空或超长");}private Set<String> ids(List<Map<String,Object>> list){Set<String> ids=new HashSet<>();for(Map<String,Object> r:list){text(r,"id",100,true);text(r,"name",200,true);check(ids.add(s(r.get("id"))),"标识重复");}return ids;}
 @GetMapping public synchronized Object get(HttpServletRequest req)throws IOException{Map<String,Object> result=new LinkedHashMap<>(read(access.web(req)));result.put("providerConfiguration",map("wechat",db.count("SELECT COUNT(*) FROM yh_wx_information")>0,"sms",db.count("SELECT COUNT(*) FROM yh_jz_sys_sms")>0,"system",true,"email",false));return ok(result);}
 @PutMapping public synchronized Object save(HttpServletRequest req,@RequestBody Map<String,Object> b)throws IOException{EhrActor a=access.web(req);Map<String,Object> old=read(a);if(EhrService.num(b.get("version"))!=EhrService.num(old.get("version")))throw new EhrException(409,"消息配置已被其他人员修改，请刷新后重试");List<Map<String,Object>> templates=rows(b.get("templates"),3000),categories=rows(b.get("categories"),1000),channels=rows(b.get("channels"),4),rules=rows(b.get("rules"),2000),history=rows(old.get("history"),200),prior=rows(old.get("templates"),3000);Set<String> tids=ids(templates),cids=ids(categories),channelIds=ids(channels);ids(rules);check(channelIds.equals(new HashSet<>(Arrays.asList("wechat","sms","system","email"))),"通知渠道配置不完整");Set<String> codes=new HashSet<>();Map<String,String> categoryChannels=new HashMap<>();for(Map<String,Object> c:categories){check(channelIds.contains(s(c.get("channel"))),"分类渠道无效");categoryChannels.put(s(c.get("id")),s(c.get("channel")));}
 for(Map<String,Object> t:templates){text(t,"code",100,true);check(s(t.get("code")).matches("[A-Za-z0-9][A-Za-z0-9_.-]{0,99}")&&codes.add(s(t.get("code")).toLowerCase(Locale.ROOT)),"模板编码无效或重复");text(t,"body",10000,false);text(t,"providerId",200,false);text(t,"scene",300,false);text(t,"audience",500,false);text(t,"url",1000,false);check(cids.contains(s(t.get("categoryId")))&&s(t.get("channel")).equals(categoryChannels.get(s(t.get("categoryId")))),"分类与消息渠道不一致");String url=s(t.get("url"));check(url.isEmpty()||url.matches("https?://[^\\s]+")||url.matches("/[A-Za-z0-9_/?&=.%#-]*"),"详情地址须为站内路径或http/https网址");Map<String,Object> p=prior.stream().filter(r->s(r.get("id")).equals(s(t.get("id")))).findFirst().orElse(null);if(p==null||!json.writeValueAsString(p).equals(json.writeValueAsString(t))){if(p!=null)history.add(map("id",UUID.randomUUID().toString(),"templateId",p.get("id"),"name",p.get("name"),"revision",p.get("revision"),"savedAt",now(),"snapshot",p));t.put("revision",p==null?1:EhrService.num(p.get("revision"))+1);t.put("updatedAt",now());}}
 for(Map<String,Object> c:channels){text(c,"sender",200,false);text(c,"description",1000,false);for(String key:Arrays.asList("quietStart","quietEnd")){String v=s(c.get(key));if(!v.isEmpty())try{java.time.LocalTime.parse(v);}catch(Exception ex){throw new EhrException(422,"免打扰时间格式无效");}}check(s(c.get("quietStart")).isEmpty()==s(c.get("quietEnd")).isEmpty(),"免打扰起止时间须同时填写");}
 for(Map<String,Object> r:rules){check(tids.contains(s(r.get("templateId"))),"发送规则关联的模板不存在");text(r,"trigger",100,true);check(Arrays.asList("manual","report_ready","assessment_ready","followup_due","plan_ready").contains(s(r.get("trigger"))),"触发场景无效");check(r.get("delayMinutes") instanceof Number&&EhrService.num(r.get("delayMinutes"))>=0&&EhrService.num(r.get("delayMinutes"))<=10080,"延迟须为0–10080分钟");text(r,"description",2000,false);}
 if(history.size()>100)history=new ArrayList<>(history.subList(history.size()-100,history.size()));Map<String,Object> next=map("version",EhrService.num(old.get("version"))+1,"templates",templates,"categories",categories,"channels",channels,"rules",rules,"history",history,"previews",old.get("previews"));write(a,next);next.put("providerConfiguration",map("wechat",db.count("SELECT COUNT(*) FROM yh_wx_information")>0,"sms",db.count("SELECT COUNT(*) FROM yh_jz_sys_sms")>0,"system",true,"email",false));return ok(next);}
 @PostMapping("/preview") public synchronized Object preview(HttpServletRequest req,@RequestBody Map<String,Object> b)throws IOException{EhrActor a=access.web(req);Map<String,Object> data=read(a),t=rows(data.get("templates"),3000).stream().filter(r->s(r.get("id")).equals(s(b.get("templateId")))).findFirst().orElseThrow(()->new EhrException(404,"消息模板不存在"));check(b.get("values") instanceof Map,"变量参数格式错误");Map<?,?> values=(Map<?,?>)b.get("values");check(values.size()<=100,"变量超过100项");Matcher matcher=VARIABLE.matcher(s(t.get("body")));StringBuffer result=new StringBuffer();Set<String> missing=new LinkedHashSet<>();while(matcher.find()){String key=matcher.group(1)==null?matcher.group(2):matcher.group(1),value=s(values.get(key));check(value.length()<=2000,"变量内容过长");if(value.trim().isEmpty()){missing.add(key);value=matcher.group();}matcher.appendReplacement(result,Matcher.quoteReplacement(value));}matcher.appendTail(result);check(result.length()<=50000,"预览内容过长");List<Map<String,Object>> previews=rows(data.get("previews"),500);Map<String,Object> record=map("id",UUID.randomUUID().toString(),"templateId",t.get("id"),"name",t.get("name"),"revision",t.get("revision"),"createdAt",now(),"missing",missing.size());previews.add(record);if(previews.size()>200)previews=new ArrayList<>(previews.subList(previews.size()-200,previews.size()));data.put("previews",previews);data.put("version",EhrService.num(data.get("version"))+1);write(a,data);return ok(map("body",result.toString(),"missing",missing,"record",record,"version",data.get("version"),"sent",false));}
 @GetMapping("/records") public Object records(HttpServletRequest req,@RequestParam(defaultValue="1") int page,@RequestParam(defaultValue="10") int limit,@RequestParam(defaultValue="") String query){EhrActor a=access.web(req);page=Math.max(1,page);limit=Math.max(10,Math.min(100,limit));check(page<=100000,"页码超出范围");String q="%"+query+"%";long total=db.count("SELECT COUNT(*) FROM yh_user_notify WHERE user_id=? AND COALESCE(title,'') LIKE ?",a.user,q);return ok(map("items",db.all("SELECT id,title,is_read isRead,send_date sentAt,read_date readAt FROM yh_user_notify WHERE user_id=? AND COALESCE(title,'') LIKE ? ORDER BY send_date DESC,id DESC LIMIT ? OFFSET ?",a.user,q,limit,(page-1)*limit),"total",total,"page",page,"limit",limit));}
}
